#include <algorithm>
#include <cstdio>
#include <functional>
#include <iostream>
#include <map>
#include <optional>
#include <queue>
#include <sstream>
#include <string>
#include <tuple>
#include <vector>

struct Job
{
    std::string name;
    long long arrival;
    long long duration;
    int priority;
};

enum class Policy { Fifo, Priority, Shortest };

struct RunResult
{
    std::vector<std::string> timeline;
    double averageWait = 0;
    long long longestWait = -1;
    std::string longestName;
    long long finished = 0;
};

// True when job a should run before job b under the policy.
static bool runsBefore(const Job& a, const Job& b, Policy policy)
{
    switch (policy)
    {
    case Policy::Fifo: return std::tie(a.arrival, a.name) < std::tie(b.arrival, b.name);
    case Policy::Priority: return std::make_tuple(-a.priority, a.arrival, a.name) < std::make_tuple(-b.priority, b.arrival, b.name);
    default: return std::tie(a.duration, a.arrival, a.name) < std::tie(b.duration, b.arrival, b.name);
    }
}

static RunResult simulate(std::vector<Job> jobs, Policy policy)
{
    std::sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) { return std::tie(a.arrival, a.name) < std::tie(b.arrival, b.name); });

    auto later = [policy](const Job& a, const Job& b) { return runsBefore(b, a, policy); };   // priority_queue puts the "largest" on top
    std::priority_queue<Job, std::vector<Job>, decltype(later)> ready(later);

    RunResult result;
    long long time = 0, totalWait = 0;
    std::size_t next = 0;
    while (next < jobs.size() || !ready.empty())
    {
        while (next < jobs.size() && jobs[next].arrival <= time) ready.push(jobs[next++]);
        if (ready.empty())
        {
            long long until = jobs[next].arrival;
            result.timeline.push_back("  " + std::to_string(time) + "-" + std::to_string(until) + " idle");
            time = until;
            continue;
        }
        Job job = ready.top();
        ready.pop();
        long long wait = time - job.arrival;
        totalWait += wait;
        if (wait > result.longestWait)
        {
            result.longestWait = wait;
            result.longestName = job.name;
        }
        result.timeline.push_back("  " + std::to_string(time) + "-" + std::to_string(time + job.duration) + " " + job.name +
                                  " (waited " + std::to_string(wait) + ")");
        time += job.duration;
    }
    result.finished = time;
    result.averageWait = jobs.empty() ? 0 : static_cast<double>(totalWait) / static_cast<double>(jobs.size());
    return result;
}

static std::string twoDecimals(double x)
{
    char buffer[64];
    std::snprintf(buffer, sizeof buffer, "%.2f", x);
    return buffer;
}

static std::optional<long long> wholeNumber(const std::string& s, long long low, long long high)
{
    if (s.empty() || s.size() > 7) return std::nullopt;
    for (char c : s)
        if (c < '0' || c > '9') return std::nullopt;
    long long n = std::stoll(s);
    if (n < low || n > high) return std::nullopt;
    return n;
}

static std::optional<Policy> parsePolicy(const std::string& s)
{
    if (s == "fifo") return Policy::Fifo;
    if (s == "priority") return Policy::Priority;
    if (s == "shortest") return Policy::Shortest;
    return std::nullopt;
}

int main()
{
    std::map<std::string, Job> jobs;
    const std::map<std::string, std::pair<std::size_t, std::string>> usage{
        { "job", { 5, "job <name> <arrival> <duration> <priority>" } }, { "run", { 2, "run <policy>" } },
        { "compare", { 1, "compare" } }, { "jobs", { 1, "jobs" } }, { "remove", { 2, "remove <name>" } } };

    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> w;
        for (std::string word; in >> word;) w.push_back(word);
        if (w.empty()) continue;

        auto known = usage.find(w[0]);
        if (known == usage.end())
        {
            std::cout << "error: unknown command '" << w[0] << "'\n";
            continue;
        }
        if (w.size() != known->second.first)
        {
            std::cout << "error: usage: " << known->second.second << '\n';
            continue;
        }

        std::vector<Job> all;
        for (const auto& [name, job] : jobs) all.push_back(job);

        if (w[0] == "job")
        {
            auto arrival = wholeNumber(w[2], 0, 1000000), duration = wholeNumber(w[3], 1, 1000000), priority = wholeNumber(w[4], 1, 9);
            if (!arrival || !duration || !priority)
                std::cout << "error: usage: " << known->second.second << '\n';
            else if (jobs.count(w[1]))
                std::cout << "error: job " << w[1] << " already exists\n";
            else
            {
                jobs[w[1]] = Job{ w[1], *arrival, *duration, static_cast<int>(*priority) };
                std::cout << "added " << w[1] << '\n';
            }
        }
        else if (w[0] == "run")
        {
            auto policy = parsePolicy(w[1]);
            if (!policy) { std::cout << "error: policy must be fifo, priority or shortest\n"; continue; }
            if (all.empty()) { std::cout << "nothing to run\n"; continue; }
            RunResult r = simulate(all, *policy);
            std::cout << "run " << w[1] << '\n';
            for (const auto& entry : r.timeline) std::cout << entry << '\n';
            std::cout << "average wait " << twoDecimals(r.averageWait) << ", longest wait " << r.longestWait << " (" << r.longestName
                      << "), finished at " << r.finished << '\n';
        }
        else if (w[0] == "compare")
        {
            if (all.empty()) { std::cout << "nothing to run\n"; continue; }
            std::vector<std::pair<std::string, RunResult>> results;
            for (auto [name, policy] : { std::pair{ "fifo", Policy::Fifo }, std::pair{ "priority", Policy::Priority }, std::pair{ "shortest", Policy::Shortest } })
                results.push_back({ name, simulate(all, policy) });
            std::stable_sort(results.begin(), results.end(), [](const auto& a, const auto& b) { return a.second.averageWait < b.second.averageWait; });
            for (const auto& [name, r] : results)
                std::cout << name << ": average wait " << twoDecimals(r.averageWait) << ", finished at " << r.finished << '\n';
            std::cout << "best: " << results[0].first << '\n';
        }
        else if (w[0] == "jobs")
        {
            if (all.empty()) { std::cout << "no jobs\n"; continue; }
            std::sort(all.begin(), all.end(), [](const Job& a, const Job& b) { return std::tie(a.arrival, a.name) < std::tie(b.arrival, b.name); });
            for (const auto& j : all)
                std::cout << j.name << " arrives " << j.arrival << ", takes " << j.duration << ", priority " << j.priority << '\n';
        }
        else
        {
            if (jobs.erase(w[1])) std::cout << "removed " << w[1] << '\n';
            else std::cout << "error: no job " << w[1] << '\n';
        }
    }
}
